css:
.side{position:fixed; right:0; top:32%; display:grid; gap:10px; z-index:5}
.side a{writing-mode:vertical-rl; padding:18px 10px; border-radius:8px 0 0 8px; letter-spacing:.18em; background:#fff; box-shadow:0 2px 10px rgba(0,0,0,.08)}
.v-more{writing-mode:vertical-rl; width:56px; height:120px; border-radius:999px; background:#8c2b30; color:#fff; display:grid; place-items:center; padding-bottom:16px; position:relative}
.v-more::after{content:"→"; position:absolute; bottom:10px; width:22px; height:22px; border-radius:50%; background:#fff; color:#8c2b30; display:grid; place-items:center; font-size:10px}
.to-top{position:absolute; right:14px; writing-mode:vertical-rl; font-size:9px; letter-spacing:.2em; color:#8a8a8a}
.to-top::after{content:''; display:block; width:1px; height:64px; background:#555; margin:10px auto 0}
